export class Employee {
    constructor(empImage, empNo, firstName, lastName, dob, mail, contactNo, joinDate, manager, projectName, roleId, status) {
        this.empImage = empImage;
        this.empNo = empNo;
        this.firstName = firstName;
        this.lastName = lastName;
        this.dob = dob;
        this.mail = mail;
        this.contactNo = contactNo;
        this.joinDate = joinDate;
        this.manager = manager;
        this.projectName = projectName;
        this.roleId = roleId;
        this.status = status;
    }
}
